// The backdrop behind the glass. It is generated by `npm run media` (scripts/lib/backdrop.mjs):
// a planner's map — topographic contours, a radial master plan and a transit line — in dark and light.
// One entry per route, or "*" for every route.
import { defineList, Environment } from "./schema.ts";

export const environments = defineList("environments.ts", Environment, [
  {
    route: "*",
    image: "env/plan",
    place: "Generated map — contours, a radial master plan and a transit line",
  },
]);

export const environmentFor = (route: string) => environments.find((e) => e.route === route) ?? environments.find((e) => e.route === "*")!;
